import type {Message, MessageChunk, ToolCall, UsageMetadata} from '../types/ai.js';
import type {ToolRegistry} from './tools/registry.js';

export function shouldContinueToolLoop(
  stopReason: string,
  pendingToolCalls: ToolCall[],
  toolRegistry: ToolRegistry | undefined
): boolean {
  return stopReason === 'tool_use' && pendingToolCalls.length > 0 && toolRegistry !== undefined;
}

export async function collectText(stream: AsyncGenerator<MessageChunk>): Promise<string> {
  let text = '';
  for await (const chunk of stream) {
    if (chunk.type === 'text') text += chunk.text;
  }
  return text;
}

export function buildToolCallMessages(pendingToolCalls: ToolCall[]): Message {
  return {
    role: 'assistant',
    content: pendingToolCalls.map(tc => ({
      type: 'tool_use' as const,
      toolUseId: tc.id,
      name: tc.name,
      input: tc.input,
    })),
  };
}

export function collectToolCalls(chunk: MessageChunk, pendingToolCalls: ToolCall[]): void {
  if (chunk.type === 'tool_use') pendingToolCalls.push(chunk.toolCall);
}

export function extractStopReason(chunk: MessageChunk): string | null {
  return chunk.type === 'stop' ? chunk.stopReason : null;
}

export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
  return chunk.type === 'stop' ? chunk.usage : undefined;
}

// A round that reported nothing adds nothing, so a turn with no reported usage stays undefined.
export function addUsage(total: UsageMetadata | undefined, next: UsageMetadata | undefined): UsageMetadata | undefined {
  if (total === undefined) return next;
  if (next === undefined) return total;
  return {
    inputTokens: total.inputTokens + next.inputTokens,
    outputTokens: total.outputTokens + next.outputTokens,
    totalTokens: total.totalTokens + next.totalTokens,
  };
}
import {addUsage, shouldContinueToolLoop} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall, UsageMetadata} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;

describe('shouldContinueToolLoop', () => {
  it('continues when the model requested a tool and a registry can run it', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, REGISTRY)).toBe(true);
  });

  it('stops when no registry is configured, whatever the model asked for', () => {
    expect(shouldContinueToolLoop('tool_use', A_TOOL, undefined)).toBe(false);
  });

  it('stops when the model named no tool', () => {
    expect(shouldContinueToolLoop('tool_use', [], REGISTRY)).toBe(false);
  });

  it('stops when the model finished for a reason other than tool use', () => {
    expect(shouldContinueToolLoop('end_turn', A_TOOL, REGISTRY)).toBe(false);
  });
});

describe('addUsage', () => {
  it('sums each token field across reported rounds and stays undefined when no round reported', () => {
    const first: UsageMetadata = {inputTokens: 11, outputTokens: 2, totalTokens: 13};
    const second: UsageMetadata = {inputTokens: 23, outputTokens: 3, totalTokens: 26};

    expect(addUsage(first, second)).toEqual({inputTokens: 34, outputTokens: 5, totalTokens: 39});
    expect(addUsage(first, undefined)).toEqual(first);
    expect(addUsage(undefined, undefined)).toBeUndefined();
  });
});
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'Usage acceptance test.'});
const session = (): ChatSession => ({
  sessionId: 'usage-session',
  userId: 'usage-user',
  entries: [{role: 'user', content: 'Use the tools.', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'lookup-1', name: 'lookup', input: {}}};
const TOOL_STOP: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;

  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const lookupRegistry = (): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'Looks up a value.', inputSchema: {type: 'object'}},
    async () => 'found'
  );
  return registry;
};

const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});

describe('afterModelResponse usage across tool rounds', () => {
  it('reports the summed usage from every provider call in a turn with two tool rounds', async () => {
    let reported: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 11, outputTokens: 2, totalTokens: 13})],
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 23, outputTokens: 3, totalTokens: 26})],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 37, outputTokens: 5, totalTokens: 42})],
      ]),
      promptBuilder,
      lookupRegistry(),
      {hooks}
    );

    await orchestrator.processMessage(session());

    expect(reported).toEqual({inputTokens: 71, outputTokens: 10, totalTokens: 81});
  });

  it('counts reported rounds while leaving a turn with no reported usage undefined', async () => {
    const reports: Array<UsageMetadata | undefined> = [];
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reports.push(usage);
      },
    };
    const withGaps = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 2, outputTokens: 1, totalTokens: 3})],
        [TOOL_CALL, TOOL_STOP],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 7, outputTokens: 4, totalTokens: 11})],
      ]),
      promptBuilder,
      lookupRegistry(),
      {hooks}
    );
    const withoutUsage = createChatOrchestrator(
      scriptedProvider([[{type: 'text', text: 'Done.'}, DONE]]),
      promptBuilder,
      undefined,
      {hooks}
    );

    await withGaps.processMessage(session());
    await withoutUsage.processMessage(session());

    expect(reports).toEqual([{inputTokens: 9, outputTokens: 5, totalTokens: 14}, undefined]);
  });
});
